\documentclass[10pt]{article}

% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=18mm]{geometry}
\usepackage{graphicx}
\usepackage{tikz}
\usepackage{tcolorbox}
\tcbuselibrary{skins,breakable}
\usepackage{enumitem}
\usepackage{xcolor}
\usepackage{helvet}
\renewcommand{\familydefault}{\sfdefault}
\setlength{\parindent}{0pt}

% Palette (cool-toned)
\definecolor{navy}{HTML}{0B1F3A}
\definecolor{teal}{HTML}{0EA5A4}
\definecolor{cyan}{HTML}{22D3EE}
\definecolor{bg}{HTML}{F7FAFF}
\definecolor{text}{HTML}{0B1F3A}
\definecolor{muted}{HTML}{5B6E86}

% Tinted card backgrounds
\definecolor{navybg}{HTML}{EFF5FF}
\definecolor{tealbg}{HTML}{ECFEFF}
\definecolor{cyanbg}{HTML}{E6FBFF}

\tcbset{
  posterbox/.style={
    enhanced,
    arc=0pt,
    boxrule=0pt,
    drop shadow={opacity=0.14},
    left=14pt,right=14pt,top=10pt,bottom=10pt,
    title filled,
  },
  navycard/.style={
    posterbox,
    colback=navybg,
    colbacktitle=navy,
    coltitle=white,
    fonttitle=\fontsize{36}{42}\selectfont\bfseries,
    borderline west={6pt}{0pt}{navy},
  },
  tealcard/.style={
    posterbox,
    colback=tealbg,
    colbacktitle=teal,
    coltitle=white,
    fonttitle=\fontsize{36}{42}\selectfont\bfseries,
    borderline west={6pt}{0pt}{teal},
  },
  cyancard/.style={
    posterbox,
    colback=cyanbg,
    colbacktitle=navy,
    coltitle=white,
    fonttitle=\fontsize{36}{42}\selectfont\bfseries,
    borderline west={6pt}{0pt}{cyan},
  },
  highlightcard/.style={
    posterbox,
    colback=navy,
    colbacktitle=navy,
    coltitle=white,
    borderline west={8pt}{0pt}{cyan},
    fonttitle=\fontsize{36}{42}\selectfont\bfseries,
  }
}

\newcommand{\metric}[2]{%
  {\fontsize{64}{72}\selectfont\bfseries\color{cyan} #1}\\[-2mm]
  {\fontsize{22}{28}\selectfont\color{white} #2}
}

\newcommand{\submetric}[2]{%
  {\fontsize{48}{56}\selectfont\bfseries\color{cyan} #1}\\[-2mm]
  {\fontsize{20}{26}\selectfont\color{white} #2}
}

\newcommand{\posterfig}[2]{%
  \centering\includegraphics[width=0.98\linewidth]{#1}\\[4mm]
  {\fontsize{20}{26}\selectfont\color{muted}\textit{#2}}%
}

\begin{document}
\pagecolor{bg}
\color{text}

% ===================== Title bar =====================
\begin{tcolorbox}[enhanced,arc=0pt,boxrule=0pt,colback=navy,left=18pt,right=18pt,top=10pt,bottom=10pt]
{\fontsize{72}{80}\selectfont\bfseries\color{white} Global Internet Usage: A Cross-Country Comparison}\\[4mm]
{\fontsize{28}{34}\selectfont\color{cyan} A data-forward snapshot of penetration, scale, behavior, and economic impact (2025)}
\end{tcolorbox}
\vspace{6mm}

% ===================== Headline stats banner =====================
\begin{tcolorbox}[enhanced,arc=0pt,boxrule=0pt,colback=navy,left=18pt,right=18pt,top=10pt,bottom=12pt]
\begin{minipage}[t]{0.45\linewidth}
\metric{\~5.56B}{Global internet users (2025)}
\end{minipage}\hfill
\begin{minipage}[t]{0.18\linewidth}
\submetric{\~68\%}{Global penetration}
\end{minipage}\hfill
\begin{minipage}[t]{0.18\linewidth}
\submetric{\$8.0T}{E-commerce (2027 est.)}
\end{minipage}\hfill
\begin{minipage}[t]{0.16\linewidth}
\submetric{143m}{Daily social media}
\end{minipage}
\end{tcolorbox}
\vspace{8mm}

% ===================== Body (2 columns) =====================
\noindent
\begin{minipage}[t]{0.49\linewidth}

\begin{tcolorbox}[cyancard,title={The World's Digital Population}]
{\fontsize{26}{34}\selectfont\color{muted}\textbf{Scale is concentrated.} China and India together account for \textbf{~2.0B} internet users — a massive share of the global digital economy.\\[6mm]
\posterfig{figures/online_population.png}{Top countries by online population (2025 est.).}
}
\end{tcolorbox}
\vspace{8mm}

\begin{tcolorbox}[tealcard,title={How People Spend Time Online}]
{\fontsize{26}{34}\selectfont
\begin{itemize}[leftmargin=18pt,itemsep=6pt,topsep=0pt]
  \item \textbf{Global average:} \textbf{~143 minutes/day} on social media (2025).
  \item Engagement is platform-driven: scale concentrates around a small set of services.
  \item Usage intensity varies widely by region (LATAM + SEA higher; Japan + Western Europe lower).
\end{itemize}
\vspace{4mm}
\posterfig{figures/platform_mau.png}{Largest platforms by monthly active users (approx.).}
}
\end{tcolorbox}

\end{minipage}\hfill
\begin{minipage}[t]{0.49\linewidth}

\begin{tcolorbox}[navycard,title={Internet Penetration Rates by Country}]
{\fontsize{26}{34}\selectfont\color{muted}\textbf{Connectivity is uneven.} High-income markets approach universal access (\textbf{95–98\%}), while large developing nations remain far below the global average.\\[6mm]
\posterfig{figures/penetration_rates.png}{Penetration ranked across selected major digital economies (2025 est.).}
\vspace{2mm}
{\fontsize{24}{30}\selectfont\color{text}
\textbf{Key contrast:} India (\textbf{~62\%}) and Nigeria (\textbf{~52\%}) imply hundreds of millions still offline.
}
}
\end{tcolorbox}
\vspace{8mm}

\begin{tcolorbox}[highlightcard,title={The Digital Economy Impact}]
{\fontsize{28}{36}\selectfont\color{white}
\textbf{Connectivity \(\to\) commerce.} Global retail e-commerce is projected to reach \textbf{\$8.0T by 2027} (up from \textbf{\$6.3T in 2024}).\\[6mm]
\begin{itemize}[leftmargin=18pt,itemsep=6pt,topsep=0pt]
  \item E-commerce now exceeds \textbf{20\%} of total retail in many markets.
  \item \textbf{Mobile} drives over \textbf{60\%} of global web traffic.
  \item Data creation accelerates to \textbf{180+ zettabytes} (2025 est.).
\end{itemize}
\vspace{6mm}
\colorbox{cyan!20}{\parbox{0.96\linewidth}{\fontsize{26}{34}\selectfont\color{white}\textbf{Takeaway:} Expanding access is one of the largest remaining levers for digital growth.}}
}
\end{tcolorbox}

\end{minipage}

\vspace{6mm}
{\fontsize{18}{24}\selectfont\color{muted}Data: compiled from the provided brief (2025 estimates). Poster format: A1 portrait.}

\end{document}
TEX

